CREATE TABLE IF NOT EXISTS gis_phase365_watchdog_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), certification_version TEXT NOT NULL, run_status TEXT NOT NULL, integrity_status TEXT NOT NULL, anomalies BIGINT NOT NULL DEFAULT 0, incident_count BIGINT NOT NULL DEFAULT 0, report JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); CREATE TABLE IF NOT EXISTS gis_phase365_incidents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), certification_version TEXT NOT NULL, severity TEXT NOT NULL, incident_type TEXT NOT NULL, details JSONB NOT NULL DEFAULT '{}'::jsonb, status TEXT NOT NULL DEFAULT 'OPEN', first_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), last_seen_at TIMESTAMPTZ NOT NULL DEFAULT now(), resolved_at TIMESTAMPTZ);